class Features:

    def __init__(self, definitions_service):
        self.definitions_service = definitions_service
        self.definitions = []

    def download_definitions(self, module):
        """
        Download available definitions for given module configuration.

        :param dict module:
        """
        query = self._build_query(module)
        if module['isEnabled']:
            self.definitions = self.definitions_service.get_definitions_as_enabled(**query)
        else:
            self.definitions = self.definitions_service.get_definitions_as_disabled(**query)

    @staticmethod
    def _build_query(module):
        return {
            'measurement_type': module['measurementType'],
            'technology': module['technology'],
            'ps2only': module['ps2Only'],
            'data_volume': module.get('dataVolume'),
            'ps_calculation': module.get('psCalculation'),
            'ps_trigger': module.get('psTrigger')
        }

    def enable(self, feature_names, enable_selected_features):
        """
        Remove disabled definitions and enable selected definitions.

        :param list(string) feature_names: Feature names to be enabled/disabled.
        :param bool enable_selected_features:
            If True - enables features with given names and leaves all other features disabled,
            If False - enables all other features and leaves features with given names disabled.
        """
        self._filter_definitions(feature_names, enable_selected_features)
        for feature in self.definitions:
            feature['isEnabled'] = True

    def _filter_definitions(self, feature_names, enable_selected_features):
        if enable_selected_features:
            self.definitions = [feature for feature in self.definitions
                                if any(name in feature.name for name in feature_names)]
        else:
            self.definitions = [feature for feature in self.definitions
                                if all(name not in feature.name for name in feature_names)]
